-- 바위게마을 1.3.9.7 : 대회 시스템
create table if not exists public.tournaments (id uuid primary key default gen_random_uuid(), title text not null, starts_at timestamptz, status text not null default 'scheduled', champion_team_id uuid, champion_name text, created_at timestamptz not null default now());
create table if not exists public.tournament_teams (id uuid primary key default gen_random_uuid(), tournament_id uuid not null references public.tournaments(id) on delete cascade, name text not null, seed int not null default 1, created_at timestamptz not null default now());
create table if not exists public.tournament_players (id uuid primary key default gen_random_uuid(), tournament_id uuid not null references public.tournaments(id) on delete cascade, team_id uuid not null references public.tournament_teams(id) on delete cascade, nickname text not null, line text not null, line_order int not null default 1, mmr int not null default 0);
create table if not exists public.tournament_matches (id uuid primary key default gen_random_uuid(), tournament_id uuid not null references public.tournaments(id) on delete cascade, round int not null, round_name text, slot int not null, team_a_id uuid references public.tournament_teams(id) on delete set null, team_b_id uuid references public.tournament_teams(id) on delete set null, team_a_name text, team_b_name text, winner_team_id uuid references public.tournament_teams(id) on delete set null, winner_name text, next_match_id uuid references public.tournament_matches(id) on delete set null, next_slot text, unique(tournament_id,round,slot));
create index if not exists tournament_teams_event_idx on public.tournament_teams(tournament_id);
create index if not exists tournament_players_event_idx on public.tournament_players(tournament_id);
create index if not exists tournament_matches_event_idx on public.tournament_matches(tournament_id);
